<template><div><section class="pro-panel"><div class="pro-section-head"><div><span class="eyebrow">Publishing pipeline</span><h1>My Predictions</h1><p>Track submissions and manage the distinction between pending and already-published picks.</p></div><RouterLink to="/tipster-dashboard/create-prediction" class="btn">+ New prediction</RouterLink></div><div v-if="predictions.length" class="td-table"><div class="td-table-head"><span>Fixture</span><span>Selection</span><span>Odds</span><span>Status</span></div><div v-for="p in predictions" :key="p._id" class="td-table-row"><div><b>{{p.fixture||'Football match'}}</b><small>{{formatDate(p.createdAt)}}</small></div><span>{{p.prediction}}</span><strong>{{Number(p.odds||0).toFixed(2)}}</strong><em :class="'td-status-pill '+p.status">{{statusLabel(p.status)}}</em></div></div><div v-else class="empty">No submitted predictions yet.</div></section><section class="pro-panel td-published-picks"><div class="pro-section-head"><div><span class="eyebrow">Live record</span><h2>Published Tipster Picks</h2><p>Approved picks are already live on BraTipsters. Do not submit them again.</p></div></div><div v-if="published.length" class="td-published-list"><RouterLink v-for="p in published" :key="p._id" :to="p.matchId?`/matches/${p.matchId}`:`/predictions/${p._id}`" class="td-published-row"><div><b>{{p.fixture||'Football match'}}</b><small>{{formatDate(p.publishedAt||p.createdAt)}}</small></div><span>{{p.prediction}}</span><strong>{{Number(p.odds||0).toFixed(2)}}</strong><em :class="'td-status-pill '+p.status">{{statusLabel(p.status)}}</em></RouterLink></div><div v-else class="empty">No published picks yet.</div></section></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{RouterLink}from'vue-router';import{api}from'../services/api';import{formatDate}from'../utils/formatters';const predictions=ref<any[]>([]);const published=computed(()=>predictions.value.filter(x=>['published','won','lost','void'].includes(x.status)));function statusLabel(v:string){return v==='published'?'Published':v==='won'?'Won':v==='lost'?'Lost':v==='void'?'Void':'Pending'}onMounted(async()=>{try{predictions.value=(await api.get('/me/tipster')).data.predictions||[]}catch{}})</script>
